# Generated by build.py from recipe.yml for recipe sftp-offer-a-single-cipher. Do not edit.
Set-Location $PSScriptRoot
cmd /c 'ssh-keygen -q -t rsa -b 3072 -N "" -f host_key'
cmd /c 'ssh-keygen -q -t rsa -b 3072 -N "" -f client_key'
$server0 = Start-Process surl -ArgumentList '--ssh-ciphers', 'aes256-ctr', '--ssh-macs', 'hmac-sha2-256', '--directory', 'site', '--hostkey', 'host_key', '--authorized-keys', 'alice:client_key.pub', 'sftp://127.0.0.1:8080/' -PassThru -NoNewWindow
Start-Sleep 1
try { sftp -v -b get.sftp -P 8080 -i client_key -o StrictHostKeyChecking=no -o UserKnownHostsFile=NUL -o GlobalKnownHostsFile=NUL alice@127.0.0.1 2>&1 } finally { Stop-Process $server0 }
